// Generated from a stock SQLite database containing native Cursor tabs/bubbles.
// The parser opens this fixture read-only; tests require neither Python nor SSH.
fn cursor_fixture() -> Vec<u8> {
    let mut bytes = vec![0; 12288];
    for (offset, hex) in [
        (0, "53514c69746520666f726d61742033001000010100402020000000020000000300000000000000000000000100000004000000000000000000000001"),
        (95, "02002e7a710d0ff800020f5c000f5c0fbf"),
        (3932, ""),
        (7893, ""),
        (12258, "1d034109636f6d706f736572446174613a6d6972726f722d637572736f72"),
    ] {
        for index in 0..hex.len() / 2 {
            bytes[offset + index] = u8::from_str_radix(&hex[index * 2..index * 2 + 2], 16).unwrap();
        }
    }
    bytes
}
